import java.util.*;
import java.io.*;

public class HeightAllTheSame {
    private static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(in.readLine());
        long N = Long.parseLong(st.nextToken());
        long M = Long.parseLong(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());

        long blocks = N * M;
        long choices = R - L + 1;
        long basePow = fastPow(choices, blocks);

        if (blocks % 2 == 1) {
            out.println(basePow);
        } else if (choices % 2 == 0) {
            out.println(basePow * ((MOD + 1) / 2) % MOD);
        } else {
            out.println((basePow + 1) * ((MOD + 1) / 2) % MOD);
        }

        in.close();
        out.close();
    }

    private static long fastPow(long base, long exponent) {
        if (exponent <= 0L) {
            return 1L;
        }
        long result = 1L;
        long b = exponent;
        long multiplyBy = base;
        while (b != 0L) {
            if ((b & 1L) == 1L) {
                result = (result * multiplyBy) % MOD;
            }
            b >>= 1;
            if (b != 0L) {
                multiplyBy = (multiplyBy * multiplyBy) % MOD;
            }
        }
        return result;
    }
}
